const updatePlaybook = `-- name: UpdatePlaybook :one
UPDATE playbooks SET name = $1, description = $2, checklists = $3, updated_at = now()
WHERE id = $4 AND archived_at IS NULL
RETURNING id, workspace_id, name, description, checklists, created_by, created_at, updated_at, archived_at
`

type UpdatePlaybookParams struct {
	Name        string      `json:"name"`
	Description string      `json:"description"`
	Checklists  []byte      `json:"checklists"`
	ID          pgtype.UUID `json:"id"`
}

func (q *Queries) UpdatePlaybook(ctx context.Context, arg UpdatePlaybookParams) (Playbook, error) {
	row := q.db.QueryRow(ctx, updatePlaybook,
		arg.Name,
		arg.Description,
		arg.Checklists,
		arg.ID,
	)
	var i Playbook
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Name,
		&i.Description,
		&i.Checklists,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.ArchivedAt,
	)
	return i, err
}

const withdrawTerms = `-- name: WithdrawTerms :exec
UPDATE terms_of_service SET withdrawn_at = now() WHERE withdrawn_at IS NULL
`

func (q *Queries) WithdrawTerms(ctx context.Context) error {
	_, err := q.db.Exec(ctx, withdrawTerms)
	return err
}
